mapper.select:
SELECT A.PROC_CD , B.PROC_NM , C.LINE_NM , A.COIL_WGT FROM TB_M47_PRD_ACT_CMN A , TB_M47_PROC B , TB_M47_LINE C WHERE B.PROC_CD = A.PROC_CD AND C.LINE_CD(+) = A.LINE_CD AND C.USE_YN(+) = 'Y' AND A.PDN_PST_DD BETWEEN #{fromDd} AND #{toDd}
AND A.PROC_CD = #{procCd}
AND A.LOT_NO LIKE #{lotNo} || '%'
ORDER BY A.PDN_PST_DD DESC, A.PROC_CD

SELECT A.PROC_CD , A.PRD_NM_CD , SUM(A.COIL_WGT) WGT FROM TB_M47_PRD_ACT_CMN A WHERE A.PDN_PST_DD BETWEEN #{fromDd} AND #{toDd}
AND A.PROC_CD IN
#{procCd}
GROUP BY A.PROC_CD , A.PRD_NM_CD ORDER BY A.PROC_CD, A.PRD_NM_CD
